define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_28.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e117712","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_28.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e117816","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the Power Distribution Unit (PDU) when servicing this item in the Integrated System Cabinet (ISC). Applying LOTO ensures a safe environment when working on this part.<\/p>","href":"t_LOTO-for-ISC-Integrated-System-Cabinet_14845718_20.html","attributes":{"data-id":"id_13106290"},"menu":{"hasChildren":false},"tocID":"id_13106290-d46e117920","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_16.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e118024","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_15.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e118128","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_14.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e118232","topics":[]},{"title":"Removing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Removes the service access vent from the magnet enclosure allowing a ladder to stand close to the magnet on the left-hand side.<\/p>","href":"t_RemovingTheServiceAccessVent_10.html","attributes":{"data-id":"id_2002970"},"menu":{"hasChildren":false},"tocID":"id_2002970-d46e118336","topics":[]},{"title":"Removing the table interface assembly","shortdesc":"<p class=\"shortdesc\">Remove the table interface (TIF) assembly from the magnet outer electronics.<\/p>","href":"t_RemovingTheTableInterfaceAssembly.html","attributes":{"data-id":"id_2021391"},"menu":{"hasChildren":false},"tocID":"id_2021391-d46e118440","topics":[]},{"title":"Installing the table interface assembly","shortdesc":"<p class=\"shortdesc\">Install a table interface (TIF) assembly in the magnet outer electronics.<\/p>","href":"t_InstallingTheTIF.html","attributes":{"data-id":"id_2012259"},"menu":{"hasChildren":false},"tocID":"id_2012259-d46e118544","topics":[]},{"title":"Installing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Installs the service access vent onto the magnet enclosure.<\/p>","href":"t_InstallingTheServiceAccessVent_10.html","attributes":{"data-id":"id_2002971"},"menu":{"hasChildren":false},"tocID":"id_2002971-d46e118648","topics":[]},{"title":"Installing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Installs the rear service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheRearServiceAccessPanel_14.html","attributes":{"data-id":"id_2002967"},"menu":{"hasChildren":false},"tocID":"id_2002967-d46e118753","topics":[]},{"title":"Installing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Installs the front service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheFrontServiceAccessPanel_15.html","attributes":{"data-id":"id_2002825"},"menu":{"hasChildren":false},"tocID":"id_2002825-d46e118857","topics":[]},{"title":"Installing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Installs the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_InstallingTheServiceAccessTrim_16.html","attributes":{"data-id":"id_2002822"},"menu":{"hasChildren":false},"tocID":"id_2002822-d46e118961","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Removing locks and tags, and restoring power to the ISC (Integrated System Cabinet) Power Distribution Unit (PDU).<\/p>","href":"t_Removing-LOTO-ISC-Pioneer_19.html","attributes":{"data-id":"id_2016646"},"menu":{"hasChildren":false},"tocID":"id_2016646-d46e119065","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_29.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e119169","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_29.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e119273","topics":[]}]});